function Resolve-ContainedPath { param([Parameter(Mandatory)][string]$Candidate,[Parameter(Mandatory)][string[]]$Roots) $full=[IO.Path]::GetFullPath($Candidate); foreach($root in $Roots){$r=[IO.Path]::GetFullPath($root).TrimEnd('\'); if($full.Equals($r,[StringComparison]::OrdinalIgnoreCase) -or $full.StartsWith($r+'\',[StringComparison]::OrdinalIgnoreCase)){return $full}}; throw "Path escapes approved containment roots: $full" }
